INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "訓練はまだ\nここからですわ", 2, 1, 1000, "調子が上がって\nきたなっ", "vo_minigame_1013_icon_1_002_001", 2, "vo_minigame_1013_icon_2_002_001", 2);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "クスクス、悪くない\n流れですわね", 2, 2, 5000, "ほらほら、\nまだいけるだろ？", "vo_minigame_1013_icon_1_003_001", 2, "vo_minigame_1013_icon_2_003_001", 2);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "すばらしい\n記録ですわ", 2, 3, 10000, "へへっ、おまえら\nやるじゃねえか！", "vo_minigame_1013_icon_1_004_001", 2, "vo_minigame_1013_icon_2_004_001", 3);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3000, "乗りに乗って\nいますわね", 2, 4, 10000, "あたしたちはまだ\n止まらねえぜ！", "vo_minigame_1013_icon_1_005_001", 3, "vo_minigame_1013_icon_2_005_001", 3);
